def show_campaigns(status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(status_value, error_code=None, meta=None):
        logs = _load("request_logs.json")
        logs = _ensure_list(logs)
        logs.append({
            "id": "knk_req_" + hashlib.sha256((now + str(time.time()) + "show_campaigns").encode("utf-8")).hexdigest()[:26],
            "endpoint": "show_campaigns",
            "status": status_value,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "meta": meta if isinstance(meta, dict) else {}
        })
        _save("request_logs.json", logs)

    def _limits_check():
        limits = _load("limits.json")
        if not isinstance(limits, dict):
            return None

        logs = _ensure_list(_load("request_logs.json"))

        rl = limits.get("rate_limit")
        if isinstance(rl, dict):
            max_req = rl.get("max_requests")
            win = rl.get("window_seconds")
            if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                cutoff = now_dt - datetime.timedelta(seconds=win)
                cnt = 0
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts.endswith("Z"):
                        try:
                            dts = datetime.datetime.fromisoformat(ts[:-1])
                        except Exception:
                            continue
                        if dts >= cutoff:
                            cnt += 1
                if cnt >= max_req:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")

        quota = limits.get("quota")
        if isinstance(quota, dict):
            max_total = quota.get("max_requests_total")
            if isinstance(max_total, int) and max_total >= 0:
                if len(logs) >= max_total:
                    return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived", "deleted"):
            _log("error", "VALIDATION_ERROR", {"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.", field="status")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", "VALIDATION_ERROR", {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR", {"field": "cursor"})
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.", field="cursor")
    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name"):
        _log("error", "VALIDATION_ERROR", {"field": "sort"})
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name.", field="sort")
    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("error", "VALIDATION_ERROR", {"field": "order"})
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc.", field="order")

    # Rate limit / quota
    lim_err = _limits_check()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    campaigns = _ensure_list(_load("campaigns.json"))

    # Business rule: show_campaigns returns campaigns where status != 'deleted'
    rows = [c for c in campaigns if isinstance(c, dict) and c.get("status") != "deleted"]

    # Optional filter by status, but cannot return deleted due to above rule
    if status is not None:
        if status == "deleted":
            rows = []
        else:
            rows = [c for c in rows if c.get("status") == status]

    def _key(c):
        v = c.get(sort)
        if sort in ("created_at", "updated_at"):
            if isinstance(v, str) and v.endswith("Z"):
                try:
                    return datetime.datetime.fromisoformat(v[:-1])
                except Exception:
                    return datetime.datetime.min
            if isinstance(v, str):
                try:
                    return datetime.datetime.fromisoformat(v.replace("Z", ""))
                except Exception:
                    return datetime.datetime.min
            return datetime.datetime.min
        # name
        return (v or "").lower() if isinstance(v, str) else ""

    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    start = 0
    if cursor:
        # Cursor is an id from the previous page; it is not an error if it's unknown => start from beginning.
        idx = None
        for i, c in enumerate(rows):
            if c.get("id") == cursor:
                idx = i
                break
        if idx is not None:
            start = idx + 1

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = page[-1].get("id") if (has_more and page) else None

    _log("ok", None, {"returned": len(page), "total": len(rows), "has_more": has_more})

    return {
        "data": page,
        "meta": {
            "limit": limit,
            "total": len(rows),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
            "status_filter": status
        }
    }

def list_characters(campaign_id, status=None, parent_entity_id=None, name=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _log(endpoint, status_code, used_credential=None, used_campaign_id=None, meta=None):
        meta = meta if isinstance(meta, dict) else {}
        logs = _load("request_logs.json")
        logs = _ensure_list(logs)
        dt = int((time.time() - t0) * 1000)
        logs.append({
            "id": "req_" + hashlib.sha256((endpoint + now + str(time.time())).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential": used_credential,
            "campaign_id": used_campaign_id,
            "status": status_code,
            "latency_ms": dt,
            "timestamp": now,
            "meta": meta
        })
        _save("request_logs.json", logs)

    def _check_limits():
        limits = _load("limits.json")
        if not isinstance(limits, dict):
            return None
        logs = _load("request_logs.json")
        logs = _ensure_list(logs)
        rl = limits.get("rate_limit")
        if isinstance(rl, dict):
            max_req = rl.get("max_requests")
            win = rl.get("window_seconds")
            if isinstance(max_req, int) and isinstance(win, int) and max_req >= 0 and win > 0:
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=win)
                n = 0
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts.endswith("Z"):
                        try:
                            dts = datetime.datetime.fromisoformat(ts[:-1])
                        except Exception:
                            continue
                        if dts >= cutoff:
                            n += 1
                if n >= max_req:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        q = limits.get("quota")
        if isinstance(q, dict):
            max_total = q.get("max_requests_total")
            if isinstance(max_total, int) and max_total >= 0:
                if len(logs) >= max_total:
                    return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    limerr = _check_limits()
    if limerr:
        _log("list_characters", limerr["error"]["code"], used_campaign_id=campaign_id)
        return limerr

    # auth ambient; if sessions.json exists, require an active session
    sessions = _load("sessions.json")
    if sessions and isinstance(sessions, list):
        ok = any(isinstance(s, dict) and s.get("status") in (None, "active", "valid") for s in sessions)
        if not ok:
            _log("list_characters", "UNAUTHORIZED", used_campaign_id=campaign_id)
            return _err("UNAUTHORIZED", "No valid session provided.")

    # validate
    ulid_cmp_re = re.compile(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$")
    ulid_ent_re = re.compile(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(campaign_id, str) or not ulid_cmp_re.match(campaign_id):
        _log("list_characters", "VALIDATION_ERROR", used_campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "Invalid campaign_id.", field="campaign_id")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deleted"):
            _log("list_characters", "VALIDATION_ERROR", used_campaign_id=campaign_id)
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if parent_entity_id is not None:
        if not isinstance(parent_entity_id, str) or not ulid_ent_re.match(parent_entity_id):
            _log("list_characters", "VALIDATION_ERROR", used_campaign_id=campaign_id)
            return _err("VALIDATION_ERROR", "Invalid parent_entity_id.", field="parent_entity_id")

    if name is not None and not isinstance(name, str):
        _log("list_characters", "VALIDATION_ERROR", used_campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "Invalid name.", field="name")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("list_characters", "VALIDATION_ERROR", used_campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "Invalid limit; must be 1-100.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log("list_characters", "VALIDATION_ERROR", used_campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    if sort is None:
        sort = "created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name"):
        _log("list_characters", "VALIDATION_ERROR", used_campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    if order is None:
        order = "asc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("list_characters", "VALIDATION_ERROR", used_campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")

    def _decode_cursor(c):
        if c is None:
            return 0
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("off:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        s = f"off:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    offset = _decode_cursor(cursor)
    if offset is None:
        _log("list_characters", "VALIDATION_ERROR", used_campaign_id=campaign_id)
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # campaign must exist and not be deleted (visibility)
    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    camp = next((c for c in campaigns if isinstance(c, dict) and c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if camp is None:
        _log("list_characters", "NOT_FOUND", used_campaign_id=campaign_id)
        return _err("NOT_FOUND", "Campaign not found.", field="campaign_id")

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []

    # business rule: list_* filter by campaign and return only rows with status='active' for requested entity_type
    # This tool offers status filter param, but rule says always active. Enforce rule.
    rows = []
    qname = (name or "").strip().lower() if isinstance(name, str) else None
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("campaign_id") != campaign_id:
            continue
        if e.get("entity_type") != "character":
            continue
        if e.get("status") != "active":
            continue
        if parent_entity_id is not None and e.get("parent_entity_id") != parent_entity_id:
            continue
        if qname:
            nm = e.get("name")
            if not isinstance(nm, str) or qname not in nm.lower():
                continue
        rows.append(e)

    reverse = (order == "desc")

    def _key(v):
        x = v.get(sort)
        if sort in ("created_at", "updated_at"):
            if isinstance(x, str) and x.endswith("Z"):
                try:
                    return datetime.datetime.fromisoformat(x[:-1])
                except Exception:
                    return datetime.datetime.min
            return datetime.datetime.min
        if isinstance(x, str):
            return x.lower()
        return ""

    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order
        }
    }
    _log("list_characters", "OK", used_campaign_id=campaign_id, meta={"returned": len(page)})
    return resp

def get_character(character_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_req_id():
        # stable-ish unique id without external deps
        base = format(int(time.time() * 1000000), "x")
        return "knk_req_" + base[:26].ljust(26, "0")

    def _enforce_limits_and_log(status_value, error_code=None):
        # enforce limits BEFORE counting this request; then log regardless
        limits = _load("limits.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        if isinstance(limits, dict):
            rl = limits.get("rate_limit")
            if isinstance(rl, dict):
                max_req = rl.get("max_requests")
                win = rl.get("window_seconds")
                if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                    cutoff = now_dt - datetime.timedelta(seconds=win)
                    cnt = 0
                    for r in logs:
                        ts = r.get("timestamp")
                        if isinstance(ts, str) and ts.endswith("Z"):
                            try:
                                dts = datetime.datetime.fromisoformat(ts[:-1])
                            except Exception:
                                continue
                            if dts >= cutoff:
                                cnt += 1
                    if cnt >= max_req:
                        # still log the refused request
                        logs.append({
                            "id": _new_req_id(),
                            "endpoint": "get_character",
                            "status": "error",
                            "error_code": "RATE_LIMIT",
                            "timestamp": now,
                            "latency_ms": int((time.time() - t0) * 1000),
                            "entity_id": character_id
                        })
                        _save("request_logs.json", logs)
                        return _err("RATE_LIMIT", "Rate limit exceeded.")

            quota = limits.get("quota")
            if isinstance(quota, dict):
                max_total = quota.get("max_requests_total")
                if isinstance(max_total, int) and max_total >= 0:
                    if len(logs) >= max_total:
                        logs.append({
                            "id": _new_req_id(),
                            "endpoint": "get_character",
                            "status": "error",
                            "error_code": "QUOTA_EXCEEDED",
                            "timestamp": now,
                            "latency_ms": int((time.time() - t0) * 1000),
                            "entity_id": character_id
                        })
                        _save("request_logs.json", logs)
                        return _err("QUOTA_EXCEEDED", "Quota exceeded.")

        logs.append({
            "id": _new_req_id(),
            "endpoint": "get_character",
            "status": status_value,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "entity_id": character_id
        })
        _save("request_logs.json", logs)
        return None

    # Validate
    if not isinstance(character_id, str):
        e = _err("VALIDATION_ERROR", "character_id must be a string.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e
    if not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", character_id):
        e = _err("VALIDATION_ERROR", "character_id is not a valid character entity ULID.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e

    # Find entity by id, ensure correct type and not deleted
    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []

    ent = None
    for r in entities:
        if isinstance(r, dict) and r.get("id") == character_id and r.get("entity_type") == "character":
            ent = r
            break

    if not ent or ent.get("status") == "deleted":
        e = _err("NOT_FOUND", "Character not found.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e

    # success
    lim = _enforce_limits_and_log("ok", None)
    if lim:
        return lim
    return {"data": ent}

