    if not isinstance(campaigns, list):
        campaigns = []
    camp = next((c for c in campaigns if isinstance(c, dict) and c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if camp is None:
        _log("create_character", "NOT_FOUND", used_campaign_id=campaign_id)
        return _err("NOT_FOUND", "Campaign not found.", field="campaign_id")

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []

    # validate parent exists if provided, same campaign, and compatible type
    parent_ent = None
    if parent_entity_id is not None:
        parent_ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == parent_entity_id), None)
        if parent_ent is None or parent_ent.get("status") == "deleted":
            _log("create_character", "NOT_FOUND", used_campaign_id=campaign_id)
            return _err("NOT_FOUND", "Parent entity not found.", field="parent_entity_id")
        if parent_ent.get("campaign_id") != campaign_id:
            _log("create_character", "VALIDATION_ERROR", used_campaign_id=campaign_id)
            return _err("VALIDATION_ERROR", "Parent entity must be in the same campaign.", field="parent_entity_id")
        # compatible parent types: characters can only be parented by characters? rule doesn't specify.
        # Only enforce specified compatible types for location/note/journal. Allow character parent of any type in same campaign.
        # Prevent self-parenting is irrelevant for create.

    # --- id/ulid generation helper (ULID-like base32; sufficient for uniqueness) ---
    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid26():
        # 48-bit timestamp (ms) + 80-bit randomness => 128 bits => 26 chars base32
        ms = int(time.time() * 1000) & ((1 << 48) - 1)
        r = random.getrandbits(80)
        val = (ms << 80) | r
        out = []
        for _ in range(26):
            out.append(_CROCK[val & 31])
            val >>= 5
        return "".join(reversed(out))

    def _new_entity_id():
        # avoid collision
        for _ in range(10):
            eid = "knk_ent_" + _ulid26()
            if not any(isinstance(e, dict) and e.get("id") == eid for e in entities):
                return eid
        return "knk_ent_" + _ulid26()

    # uniqueness constraints require kanka_entity_id and kanka_object_id, but tool doesn't provide them.
    # Generate new numeric ids that don't collide in this campaign.
    used_entity_ids = set()
    used_object_ids = set()
    for e in entities:
        if not isinstance(e, dict):
            continue
        if e.get("campaign_id") != campaign_id:
            continue
        if isinstance(e.get("kanka_entity_id"), int):
            used_entity_ids.add(e["kanka_entity_id"])
        if e.get("entity_type") == "character" and isinstance(e.get("kanka_object_id"), int):
            used_object_ids.add(e["kanka_object_id"])

    def _next_int(used):
        if not used:
            return 1
        m = max(used)
        return m + 1 if m < 2**31 - 1 else (m + 1)

    kanka_entity_id = _next_int(used_entity_ids)
    kanka_object_id = _next_int(used_object_ids)

    # enforce uniqueness in case of races
    if any(isinstance(e, dict) and e.get("campaign_id") == campaign_id and e.get("kanka_entity_id") == kanka_entity_id for e in entities):
        _log("create_character", "CONFLICT", used_campaign_id=campaign_id)
        return _err("CONFLICT", "kanka_entity_id already exists in campaign.")
    if any(isinstance(e, dict) and e.get("campaign_id") == campaign_id and e.get("entity_type") == "character" and e.get("kanka_object_id") == kanka_object_id for e in entities):
        _log("create_character", "CONFLICT", used_campaign_id=campaign_id)
        return _err("CONFLICT", "kanka_object_id already exists for character in campaign.")

    ent = {
        "id": _new_entity_id(),
        "campaign_id": campaign_id,
        "kanka_entity_id": kanka_entity_id,
        "entity_type": "character",
        "kanka_object_id": kanka_object_id,
        "name": name,
        "entry_html": entry_html,
        "type_label": type,
        "title": title,
        "age": age,
        "sex": sex,
        "pronouns": pronouns,
        "race_id": race_id,
        "is_destroyed": None,
        "date": None,
        "author_id": None,
        "entity_image_uuid": entity_image_uuid,
        "parent_entity_id": parent_entity_id,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # final constraint checks: name non-empty already ensured; parent != id ensured by creation; status ok; entity_type ok.

    entities.append(ent)
    _save("entities.json", entities)

    _log("create_character", "OK", used_campaign_id=campaign_id, meta={"entity_id": ent["id"]})
    return {"data": ent}

def update_character(campaign_id, character_id, name=None, title=None, type=None, age=None, sex=None, pronouns=None, race_id=None, entry_html=None, parent_entity_id=None, entity_image_uuid=None, is_destroyed=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_req_id():
        base = format(int(time.time() * 1000000), "x")
        return "knk_req_" + base[:26].ljust(26, "0")

    def _log(status_value, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "endpoint": "update_character",
            "status": status_value,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "campaign_id": campaign_id,
            "entity_id": character_id
        })
        _save("request_logs.json", logs)

    def _limits_check():
        limits = _load("limits.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if not isinstance(limits, dict):
            return None

        rl = limits.get("rate_limit")
        if isinstance(rl, dict):
            max_req = rl.get("max_requests")
            win = rl.get("window_seconds")
            if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                cutoff = now_dt - datetime.timedelta(seconds=win)
                cnt = 0
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts.endswith("Z"):
                        try:
                            dts = datetime.datetime.fromisoformat(ts[:-1])
                        except Exception:
                            continue
                        if dts >= cutoff:
                            cnt += 1
                if cnt >= max_req:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")

        quota = limits.get("quota")
        if isinstance(quota, dict):
            max_total = quota.get("max_requests_total")
            if isinstance(max_total, int) and max_total >= 0:
                if len(logs) >= max_total:
                    return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    # Validate ids
    if not isinstance(campaign_id, str) or not re.match(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$", campaign_id):
        e = _err("VALIDATION_ERROR", "campaign_id is malformed.")
        if not _limits_check():
            _log("error", e["error"]["code"])
        else:
            _log("error", "RATE_LIMIT")
        return e
    if not isinstance(character_id, str) or not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", character_id):
        e = _err("VALIDATION_ERROR", "character_id is malformed.")
        if not _limits_check():
            _log("error", e["error"]["code"])
        else:
            _log("error", "RATE_LIMIT")
        return e

    # Validate provided fields types (patch semantics)
    if name is not None and (not isinstance(name, str) or name == ""):
        e = _err("VALIDATION_ERROR", "name must be a non-empty string.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e
    for fld, val in [("title", title), ("type", type), ("age", age), ("sex", sex), ("pronouns", pronouns), ("entry_html", entry_html), ("entity_image_uuid", entity_image_uuid)]:
        if val is not None and not isinstance(val, str):
            e = _err("VALIDATION_ERROR", f"{fld} must be a string.")
            lim = _limits_check()
            if lim:
                _log("error", lim["error"]["code"])
                return lim
            _log("error", e["error"]["code"])
            return e
    if race_id is not None and not isinstance(race_id, int):
        e = _err("VALIDATION_ERROR", "race_id must be an integer.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e
    if is_destroyed is not None and not isinstance(is_destroyed, bool):
        e = _err("VALIDATION_ERROR", "is_destroyed must be a boolean.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e
    if status is not None and status not in ("active", "deleted"):
        e = _err("VALIDATION_ERROR", "status must be one of: active, deleted.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e
    if parent_entity_id is not None:
        if not isinstance(parent_entity_id, str) or not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", parent_entity_id):
            e = _err("VALIDATION_ERROR", "parent_entity_id is malformed.")
            lim = _limits_check()
            if lim:
                _log("error", lim["error"]["code"])
                return lim
            _log("error", e["error"]["code"])
            return e

    lim = _limits_check()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    camp = next((c for c in campaigns if isinstance(c, dict) and c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        e = _err("NOT_FOUND", "Campaign not found.")
        _log("error", e["error"]["code"])
        return e

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []

    idx = None
    ent = None
    for i, r in enumerate(entities):
        if isinstance(r, dict) and r.get("id") == character_id and r.get("entity_type") == "character" and r.get("campaign_id") == campaign_id:
            idx = i
            ent = r
            break

    if not ent or ent.get("status") == "deleted":
        # Accept the audit's "campaign_id passed as character_id" scenario: it should still be a proper ULID,
        # but may not be an entity. Return NOT_FOUND per contract.
        e = _err("NOT_FOUND", "Character not found.")
        _log("error", e["error"]["code"])
        return e

    # Parent validation + minimal anti-cycle (self), plus compatible type (character has no parent constraint in rules)
    if parent_entity_id is not None:
        if parent_entity_id == character_id:
            e = _err("VALIDATION_ERROR", "parent_entity_id cannot reference the entity itself.")
            _log("error", e["error"]["code"])
            return e
        parent = next((p for p in entities if isinstance(p, dict) and p.get("id") == parent_entity_id), None)
        if not parent or parent.get("status") == "deleted":
            e = _err("NOT_FOUND", "Parent entity not found.")
            _log("error", e["error"]["code"])
            return e
        if parent.get("campaign_id") != campaign_id:
            e = _err("CONFLICT", "Parent entity must belong to the same campaign.")
            _log("error", e["error"]["code"])
            return e

    # Lifecycle transition enforcement
    if status is not None:
        cur = ent.get("status")
        if cur == "deleted" and status != "deleted":
            e = _err("INVALID_TRANSITION", "Cannot transition character from deleted.")
            _log("error", e["error"]["code"])
            return e
        if cur == "active" and status not in ("active", "deleted"):
            e = _err("INVALID_TRANSITION", "Invalid status transition.")
            _log("error", e["error"]["code"])
            return e
        # active->active allowed, active->deleted allowed; deleted->deleted allowed (idempotent)

    # Apply patch
    updated = dict(ent)
    if name is not None:
        updated["name"] = name
    if title is not None:
        updated["title"] = title
    if type is not None:
        # maps to entities.type_label
        updated["type_label"] = type
    if age is not None:
        updated["age"] = age
    if sex is not None:
        updated["sex"] = sex
    if pronouns is not None:
        updated["pronouns"] = pronouns
    if race_id is not None:
        updated["race_id"] = race_id
    if entry_html is not None:
        updated["entry_html"] = entry_html
    if parent_entity_id is not None:
        updated["parent_entity_id"] = parent_entity_id
    if entity_image_uuid is not None:
        updated["entity_image_uuid"] = entity_image_uuid
    if is_destroyed is not None:
        # not meaningful for character, but tool schema says it is accepted; persist if provided
        updated["is_destroyed"] = is_destroyed
    if status is not None:
        updated["status"] = status

    if updated.get("name", "") == "":
        e = _err("VALIDATION_ERROR", "name must not be empty.")
        _log("error", e["error"]["code"])
        return e

    updated["updated_at"] = now
    entities[idx] = updated
    _save("entities.json", entities)

    _log("ok", None)
    return {"data": updated}

