def list_locations(campaign_id, status=None, parent_entity_id=None, name=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, message, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"knk_req_{int(time.time()*1000)}",
            "endpoint": "list_locations",
            "status": status_code,
            "message": message,
            "campaign_id": campaign_id,
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(campaign_id, str) or not re.match(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$", campaign_id):
            _log("error", "validation_error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "campaign_id is invalid.")

        if status is not None:
            if not isinstance(status, str) or status not in ("active", "deleted"):
                _log("error", "validation_error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "status must be one of: active, deleted.")

        if parent_entity_id is not None:
            if not isinstance(parent_entity_id, str) or not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", parent_entity_id):
                _log("error", "validation_error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "parent_entity_id is invalid.")

        if name is not None and not isinstance(name, str):
            _log("error", "validation_error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "name must be a string.")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log("error", "validation_error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

        if cursor is not None and not isinstance(cursor, str):
            _log("error", "validation_error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a string.")

        if sort is None:
            sort = "created_at"
        if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name"):
            _log("error", "validation_error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name.")

        if order is None:
            order = "asc"
        if not isinstance(order, str) or order not in ("asc", "desc"):
            _log("error", "validation_error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")

        campaigns = _load("campaigns.json")
        if not isinstance(campaigns, list):
            campaigns = []
        camp = next((c for c in campaigns if c.get("id") == campaign_id and c.get("status") != "deleted"), None)
        if not camp:
            _log("error", "not_found", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Campaign not found.")

        entities = _load("entities.json")
        if not isinstance(entities, list):
            entities = []

        # Business rule: All list_* tools filter by campaign and return only rows with status='active' for requested entity_type.
        # The tool allows status filter, but we must enforce rule; if status != 'active', return empty set.
        if status is not None and status != "active":
            _log("ok", "listed", {"total": 0})
            return {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}

        rows = [e for e in entities if e.get("campaign_id") == campaign_id and e.get("entity_type") == "location" and e.get("status") == "active"]

        if parent_entity_id is not None:
            rows = [e for e in rows if e.get("parent_entity_id") == parent_entity_id]

        if name is not None:
            q = name.casefold()
            rows = [e for e in rows if isinstance(e.get("name"), str) and q in e.get("name").casefold()]

        # Sort
        reverse = (order == "desc")
        def _key(e):
            v = e.get(sort)
            if sort in ("created_at", "updated_at"):
                return v or ""
            return (v or "").casefold()
        rows.sort(key=_key, reverse=reverse)

        # Cursor is an opaque offset for this implementation: "offset:<n>"
        offset = 0
        if cursor:
            m = re.match(r"^offset:(\d+)$", cursor)
            if not m:
                _log("error", "validation_error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            offset = int(m.group(1))

        total = len(rows)
        page = rows[offset:offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = f"offset:{next_offset}" if has_more else None

        _log("ok", "listed", {"total": total, "returned": len(page)})
        return {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
    except Exception as e:
        _log("error", "internal_error", {"error_code": "INTERNAL_ERROR"})
        return _err("VALIDATION_ERROR", "Internal error.", detail=str(e))

def get_location(location_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_req_id():
        base = format(int(time.time() * 1000000), "x")
        return "knk_req_" + base[:26].ljust(26, "0")

    def _enforce_limits_and_log(status_value, error_code=None):
        limits = _load("limits.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        if isinstance(limits, dict):
            rl = limits.get("rate_limit")
            if isinstance(rl, dict):
                max_req = rl.get("max_requests")
                win = rl.get("window_seconds")
                if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                    cutoff = now_dt - datetime.timedelta(seconds=win)
                    cnt = 0
                    for r in logs:
                        ts = r.get("timestamp")
                        if isinstance(ts, str) and ts.endswith("Z"):
                            try:
                                dts = datetime.datetime.fromisoformat(ts[:-1])
                            except Exception:
                                continue
                            if dts >= cutoff:
                                cnt += 1
                    if cnt >= max_req:
                        logs.append({
                            "id": _new_req_id(),
                            "endpoint": "get_location",
                            "status": "error",
                            "error_code": "RATE_LIMIT",
                            "timestamp": now,
                            "latency_ms": int((time.time() - t0) * 1000),
                            "entity_id": location_id
                        })
                        _save("request_logs.json", logs)
                        return _err("RATE_LIMIT", "Rate limit exceeded.")

            quota = limits.get("quota")
            if isinstance(quota, dict):
                max_total = quota.get("max_requests_total")
                if isinstance(max_total, int) and max_total >= 0 and len(logs) >= max_total:
                    logs.append({
                        "id": _new_req_id(),
                        "endpoint": "get_location",
                        "status": "error",
                        "error_code": "QUOTA_EXCEEDED",
                        "timestamp": now,
                        "latency_ms": int((time.time() - t0) * 1000),
                        "entity_id": location_id
                    })
                    _save("request_logs.json", logs)
                    return _err("QUOTA_EXCEEDED", "Quota exceeded.")

        logs.append({
            "id": _new_req_id(),
            "endpoint": "get_location",
            "status": status_value,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "entity_id": location_id
        })
        _save("request_logs.json", logs)
        return None

    if not isinstance(location_id, str):
        e = _err("VALIDATION_ERROR", "location_id must be a string.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e
    if not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", location_id):
        e = _err("VALIDATION_ERROR", "location_id is not a valid location entity ULID.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []

    ent = None
    for r in entities:
        if isinstance(r, dict) and r.get("id") == location_id and r.get("entity_type") == "location":
            ent = r
            break

    if not ent or ent.get("status") == "deleted":
        e = _err("NOT_FOUND", "Location not found.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e

    lim = _enforce_limits_and_log("ok", None)
    if lim:
        return lim
    return {"data": ent}

def create_location(campaign_id, name, entry=None, type=None, location_id=None, tags=None, is_destroyed=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": "create_location",
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Ambient auth: look for any working context; if store has none, deny.
    credentials = _load("credentials.json")
    if isinstance(credentials, list) and credentials:
        cred = next((c for c in credentials if c.get("status") in (None, "active", "enabled")), credentials[0])
        credential_id = cred.get("id")
    else:
        credential_id = None

    # Validate inputs
    pat_cmp = re.compile(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$")
    pat_ent = re.compile(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$")
    pat_tag = re.compile(r"^knk_tag_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(campaign_id, str) or not pat_cmp.match(campaign_id):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is invalid.", field="campaign_id")
    if not isinstance(name, str) or len(name.strip()) < 1:
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be non-empty.", field="name")
    if entry is not None and not isinstance(entry, str):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "entry must be a string.", field="entry")
    if type is not None and not isinstance(type, str):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "type must be a string.", field="type")
    if location_id is not None and (not isinstance(location_id, str) or not pat_ent.match(location_id)):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "location_id is invalid.", field="location_id")
    if tags is not None:
        if not isinstance(tags, list):
            _log("error", credential_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tags must be an array of tag IDs.", field="tags")
        for i, tid in enumerate(tags):
            if not isinstance(tid, str) or not pat_tag.match(tid):
                _log("error", credential_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "tags contains an invalid tag id.", field=f"tags[{i}]")
    if is_destroyed is not None and not isinstance(is_destroyed, bool):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_destroyed must be boolean.", field="is_destroyed")

    campaigns = _load("campaigns.json")
    camp = next((c for c in campaigns if c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        _log("error", credential_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    entities = _load("entities.json")

    # Validate parent (must be location, same campaign, active, no cycles; and no self-parenting (handled by later id))
    parent_id = None
    if location_id is not None:
        parent = next((e for e in entities if e.get("id") == location_id), None)
        if not parent or parent.get("campaign_id") != campaign_id or parent.get("status") != "active":
            _log("error", credential_id, "NOT_FOUND")
            return _err("NOT_FOUND", "Parent location not found in campaign.", location_id=location_id)
        if parent.get("entity_type") != "location":
            _log("error", credential_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parent must be a location.", field="location_id")
        parent_id = location_id

    # Validate tags exist and active in campaign; then we will replace assignments for this entity.
    tag_rows = _load("tags.json")
    tag_ids = []
    if tags is not None:
        seen = set()
        for tid in tags:
            if tid in seen:
                continue
            seen.add(tid)
            trow = next((t for t in tag_rows if t.get("id") == tid and t.get("campaign_id") == campaign_id and t.get("status") == "active"), None)
            if not trow:
                _log("error", credential_id, "NOT_FOUND")
                return _err("NOT_FOUND", "Tag not found or not accessible in campaign.", tag_id=tid)
            tag_ids.append(tid)

    # Helper: basic html detection/wrapping
    def _to_html(s):
        if s is None:
            return None
        x = s.strip()
        if x == "":
            return ""
        if re.search(r"</?\w+[^>]*>", x):
            return s
        return f"<p>{s}</p>"

    # ID generators
    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _gen_id(prefix):
        return prefix + "".join(random.choice(_ALPH) for _ in range(26))

    def _new_unique_id(prefix, existing):
        existing_set = set(existing)
        for _ in range(200):
            nid = _gen_id(prefix)
            if nid not in existing_set:
                return nid
        return None

    # Enforce uniqueness: (campaign_id, entity_type, kanka_object_id) and (campaign_id, kanka_entity_id)
    # Since we are local, generate new numeric ids that are unused in this campaign.
    used_obj = {e.get("kanka_object_id") for e in entities if e.get("campaign_id") == campaign_id and e.get("entity_type") == "location"}
    used_ent = {e.get("kanka_entity_id") for e in entities if e.get("campaign_id") == campaign_id}

    def _next_int(used):
        v = 1
        while v in used:
            v += 1
        return v

    kanka_object_id = _next_int(used_obj)
    kanka_entity_id = _next_int(used_ent)

    now = _now()
    new_id = _new_unique_id("knk_ent_", [e.get("id") for e in entities])
    if not new_id:
        _log("error", credential_id, "CONFLICT")
        return _err("CONFLICT", "Unable to generate unique entity id.")

    row = {
        "id": new_id,
        "campaign_id": campaign_id,
        "kanka_entity_id": int(kanka_entity_id),
        "entity_type": "location",
        "kanka_object_id": int(kanka_object_id),
        "name": name,
        "entry_html": _to_html(entry),
        "type_label": type,
        "title": None,
        "age": None,
        "sex": None,
        "pronouns": None,
        "race_id": None,
        "is_destroyed": is_destroyed,
        "date": None,
        "author_id": None,
        "entity_image_uuid": None,
        "parent_entity_id": parent_id,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Prevent self-parenting (not possible here) and ensure parent chain doesn't form cycle with new id (none exists yet)
    # Persist entity
    entities.append(row)
    _save("entities.json", entities)

    # Replace entity_tags assignments if tags provided, else leave as-is? Rule: "When tools accept tags ... replaced to match provided list."
    if tags is not None:
        entity_tags = _load("entity_tags.json")
        # remove existing assignments for entity
        entity_tags = [et for et in entity_tags if et.get("entity_id") != new_id]
        # add requested assignments
        existing_et_ids = {et.get("id") for et in entity_tags}
        def _new_et_id():
            return _new_unique_id("knk_etg_", existing_et_ids) or f"knk_etg_{int(time.time()*1000)}_{random.randint(1000,9999)}"
        for tid in tag_ids:
            et = {
                "id": _new_et_id(),
                "campaign_id": campaign_id,
                "entity_id": new_id,
                "tag_id": tid,
                "created_at": now,
                "updated_at": now,
            }
            entity_tags.append(et)
        _save("entity_tags.json", entity_tags)

    _log("ok", credential_id, None)
    return {"data": row}

def update_location(campaign_id, location_id, name=None, entry=None, type=None, new_parent_location_id=None, tags=None, is_destroyed=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
