            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    credentials = _load("credentials.json")
    if isinstance(credentials, list) and credentials:
        cred = next((c for c in credentials if c.get("status") in (None, "active", "enabled")), credentials[0])
        credential_id = cred.get("id")
    else:
        credential_id = None

    pat_cmp = re.compile(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$")
    pat_ent = re.compile(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$")
    pat_tag = re.compile(r"^knk_tag_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(campaign_id, str) or not pat_cmp.match(campaign_id):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is invalid.", field="campaign_id")
    if not isinstance(location_id, str) or not pat_ent.match(location_id):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "location_id is invalid.", field="location_id")

    if name is not None and (not isinstance(name, str) or len(name.strip()) < 1):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if entry is not None and not isinstance(entry, str):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "entry must be a string.", field="entry")
    if type is not None and not isinstance(type, str):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "type must be a string.", field="type")
    if new_parent_location_id is not None and (not isinstance(new_parent_location_id, str) or not pat_ent.match(new_parent_location_id)):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "new_parent_location_id is invalid.", field="new_parent_location_id")
    if tags is not None:
        if not isinstance(tags, list):
            _log("error", credential_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "tags must be an array of tag IDs.", field="tags")
        for i, tid in enumerate(tags):
            if not isinstance(tid, str) or not pat_tag.match(tid):
                _log("error", credential_id, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "tags contains an invalid tag id.", field=f"tags[{i}]")
    if is_destroyed is not None and not isinstance(is_destroyed, bool):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_destroyed must be boolean.", field="is_destroyed")

    campaigns = _load("campaigns.json")
    camp = next((c for c in campaigns if c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        _log("error", credential_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    entities = _load("entities.json")
    idx = next((i for i, e in enumerate(entities) if e.get("id") == location_id), None)
    if idx is None:
        _log("error", credential_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Location not found.", location_id=location_id)
    ent = entities[idx]
    if ent.get("campaign_id") != campaign_id or ent.get("entity_type") != "location" or ent.get("status") != "active":
        _log("error", credential_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Location not found in campaign.", location_id=location_id)

    # HTML wrapping
    def _to_html(s):
        if s is None:
            return None
        x = s.strip()
        if x == "":
            return ""
        if re.search(r"</?\w+[^>]*>", x):
            return s
        return f"<p>{s}</p>"

    # Parent update validation (compatible type, same campaign, active; prevent cycles/self)
    if new_parent_location_id is not None:
        if new_parent_location_id == location_id:
            _log("error", credential_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Location cannot be its own parent.", field="new_parent_location_id")

        parent = next((e for e in entities if e.get("id") == new_parent_location_id), None)
        if not parent or parent.get("campaign_id") != campaign_id or parent.get("status") != "active":
            _log("error", credential_id, "NOT_FOUND")
            return _err("NOT_FOUND", "Parent location not found in campaign.", new_parent_location_id=new_parent_location_id)
        if parent.get("entity_type") != "location":
            _log("error", credential_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Parent must be a location.", field="new_parent_location_id")

        # Cycle check: walk up from parent to root; must not encounter self
        seen = set()
        cur = parent
        while cur is not None:
            cid = cur.get("id")
            if cid == location_id:
                _log("error", credential_id, "CONFLICT")
                return _err("CONFLICT", "Parent assignment would create a cycle.")
            if cid in seen:
                break
            seen.add(cid)
            pid = cur.get("parent_entity_id")
            if not pid:
                break
            cur = next((e for e in entities if e.get("id") == pid and e.get("campaign_id") == campaign_id), None)

    # Tag validation + replace if provided
    tag_ids = None
    if tags is not None:
        tag_rows = _load("tags.json")
        tag_ids = []
        seen = set()
        for tid in tags:
            if tid in seen:
                continue
            seen.add(tid)
            trow = next((t for t in tag_rows if t.get("id") == tid and t.get("campaign_id") == campaign_id and t.get("status") == "active"), None)
            if not trow:
                _log("error", credential_id, "NOT_FOUND")
                return _err("NOT_FOUND", "Tag not found or not accessible in campaign.", tag_id=tid)
            tag_ids.append(tid)

    # Apply patch semantics
    changed = False
    if name is not None and name != ent.get("name"):
        ent["name"] = name
        changed = True
    if entry is not None:
        html = _to_html(entry)
        if html != ent.get("entry_html"):
            ent["entry_html"] = html
            changed = True
    if type is not None and type != ent.get("type_label"):
        ent["type_label"] = type
        changed = True
    if is_destroyed is not None and is_destroyed != ent.get("is_destroyed"):
        ent["is_destroyed"] = is_destroyed
        changed = True
    if new_parent_location_id is not None:
        if new_parent_location_id != ent.get("parent_entity_id"):
            ent["parent_entity_id"] = new_parent_location_id
            changed = True

    now = _now()
    if changed:
        ent["updated_at"] = now
        entities[idx] = ent
        _save("entities.json", entities)

    if tags is not None:
        entity_tags = _load("entity_tags.json")
        before = len(entity_tags)
        entity_tags = [et for et in entity_tags if et.get("entity_id") != location_id]
        existing_ids = {et.get("id") for et in entity_tags}
        _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def _gen_id(prefix):
            return prefix + "".join(random.choice(_ALPH) for _ in range(26))
        def _new_unique_id(prefix):
            for _ in range(200):
                nid = _gen_id(prefix)
                if nid not in existing_ids:
                    existing_ids.add(nid)
                    return nid
            return f"{prefix}{int(time.time()*1000)}_{random.randint(1000,9999)}"
        for tid in tag_ids:
            entity_tags.append({
                "id": _new_unique_id("knk_etg_"),
                "campaign_id": campaign_id,
                "entity_id": location_id,
                "tag_id": tid,
                "created_at": now,
                "updated_at": now,
            })
        after = len(entity_tags)
        if before != after or True:
            _save("entity_tags.json", entity_tags)
        changed = True  # tags update counts as an effect

    if not changed:
        # Real services typically return the resource even if no fields changed.
        _log("ok", credential_id, None)
        return {"data": ent, "meta": {"changed": False}}

    _log("ok", credential_id, None)
    return {"data": ent, "meta": {"changed": True}}

