            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "campaign_id": campaign_id,
            "entity_id": location_id
        })
        _save("request_logs.json", logs)

    def _limits_check():
        limits = _load("limits.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit")
        if isinstance(rl, dict):
            max_req = rl.get("max_requests")
            win = rl.get("window_seconds")
            if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                cutoff = now_dt - datetime.timedelta(seconds=win)
                cnt = 0
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts.endswith("Z"):
                        try:
                            dts = datetime.datetime.fromisoformat(ts[:-1])
                        except Exception:
                            continue
                        if dts >= cutoff:
                            cnt += 1
                if cnt >= max_req:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        quota = limits.get("quota")
        if isinstance(quota, dict):
            max_total = quota.get("max_requests_total")
            if isinstance(max_total, int) and max_total >= 0 and len(logs) >= max_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    if not isinstance(campaign_id, str) or not re.match(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$", campaign_id):
        e = _err("VALIDATION_ERROR", "campaign_id is malformed.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e
    if not isinstance(location_id, str) or not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", location_id):
        e = _err("VALIDATION_ERROR", "location_id is malformed.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e

    lim = _limits_check()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    camp = next((c for c in campaigns if isinstance(c, dict) and c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        e = _err("NOT_FOUND", "Campaign not found.")
        _log("error", e["error"]["code"])
        return e

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []
    idx = None
    ent = None
    for i, r in enumerate(entities):
        if isinstance(r, dict) and r.get("id") == location_id and r.get("entity_type") == "location" and r.get("campaign_id") == campaign_id:
            idx = i
            ent = r
            break
    if not ent or ent.get("status") == "deleted":
        e = _err("NOT_FOUND", "Location not found.")
        _log("error", e["error"]["code"])
        return e

    ent2 = dict(ent)
    ent2["status"] = "deleted"
    ent2["updated_at"] = now
    entities[idx] = ent2
    _save("entities.json", entities)

    _log("ok", None)
    return {"data": ent2}

def list_posts(campaign_id, entity_id, limit=None, cursor=None, sort=None, status=None, **_extra):
    import json, os, datetime, re, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": "list_posts",
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    credentials = _load("credentials.json")
    if isinstance(credentials, list) and credentials:
        cred = next((c for c in credentials if c.get("status") in (None, "active", "enabled")), credentials[0])
        credential_id = cred.get("id")
    else:
        credential_id = None

    pat_cmp = re.compile(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$")
    pat_ent = re.compile(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$")

    if not isinstance(campaign_id, str) or not pat_cmp.match(campaign_id):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "campaign_id is invalid.", field="campaign_id")
    if not isinstance(entity_id, str) or not pat_ent.match(entity_id):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "entity_id is invalid.", field="entity_id")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")

    allowed_sort = {"position", "-position", "created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"}
    if sort is None:
        sort = "position"
    if not isinstance(sort, str) or sort not in allowed_sort:
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid.", field="sort", allowed=sorted(list(allowed_sort)))

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "deleted"):
        _log("error", credential_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid.", field="status")

    campaigns = _load("campaigns.json")
    camp = next((c for c in campaigns if c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        _log("error", credential_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Campaign not found.", campaign_id=campaign_id)

    entities = _load("entities.json")
    ent = next((e for e in entities if e.get("id") == entity_id and e.get("campaign_id") == campaign_id), None)
    # Rule: list_posts requires entity exists in same campaign and is active.
    if not ent or ent.get("status") != "active":
        _log("error", credential_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Entity not found or not accessible in campaign.", entity_id=entity_id)

    posts = _load("posts.json")
    rows = [p for p in posts if p.get("campaign_id") == campaign_id and p.get("entity_id") == entity_id and p.get("status") == status]

    def _dt(s):
        # ISO Z safe parse for sorting. Unknown -> minimal.
        if not isinstance(s, str):
            return datetime.datetime.min
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return datetime.datetime.min

    # Sorting
    if sort in ("position", "-position"):
        # Kanka rule for list_posts (active): ordered by (position asc nulls last, created_at asc)
        # For deleted/other sorts, we apply requested.
        if status == "active" and sort == "position":
            def key(p):
                pos = p.get("position")
                return (pos is None, pos if isinstance(pos, int) else 0, _dt(p.get("created_at")))
            rows.sort(key=key)
        else:
            reverse = sort.startswith("-")
            def pos_key(p):
                pos = p.get("position")
                # For generic sort: None last in asc, first in desc
                return (pos is None, pos if isinstance(pos, int) else 0)
            rows.sort(key=pos_key, reverse=reverse)
    elif sort in ("created_at", "-created_at"):
        rows.sort(key=lambda p: _dt(p.get("created_at")), reverse=sort.startswith("-"))
    elif sort in ("updated_at", "-updated_at"):
        rows.sort(key=lambda p: _dt(p.get("updated_at")), reverse=sort.startswith("-"))
    elif sort in ("name", "-name"):
        rows.sort(key=lambda p: (p.get("name") or "").lower(), reverse=sort.startswith("-"))

    # Cursor pagination: cursor encodes offset as base64("o:<int>")
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("error", credential_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("o:"):
                raise ValueError("bad cursor")
            offset = int(s.split(":", 1)[1])
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            _log("error", credential_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    total = len(rows)
    page = rows[offset: offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        nxt = f"o:{offset + limit}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(nxt).decode("utf-8").rstrip("=")

    _log("ok", credential_id, None)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "status": status,
        },
    }

