        return bool(re.search(r"<[^>]+>", s))

    def _to_html_entry(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("entry must be a string")
        if s.strip() == "":
            return ""
        if _is_html(s):
            return s
        return "<p>" + html.escape(s) + "</p>"

    try:
        pat_cmp = re.compile(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$")
        pat_ent = re.compile(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$")
        pat_pst = re.compile(r"^knk_pst_[0-9A-HJKMNP-TV-Z]{26}$")
        if not isinstance(campaign_id, str) or not pat_cmp.match(campaign_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed campaign_id.")
        if not isinstance(entity_id, str) or not pat_ent.match(entity_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed entity_id.")
        if not isinstance(post_id, str) or not pat_pst.match(post_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed post_id.")
        if name is not None:
            if not isinstance(name, str) or len(name) < 1 or name.strip() == "":
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")
        if position is not None:
            if not isinstance(position, int):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "position must be an integer.")
            if position < 0:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "position must be >= 0.")
        if visibility_id is not None and not isinstance(visibility_id, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "visibility_id must be an integer.")
        if entry is not None:
            try:
                entry_html = _to_html_entry(entry)
            except ValueError:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "entry must be a string when provided.")
        else:
            entry_html = None
    except Exception:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid input.")

    try:
        campaigns = _load("campaigns.json")
        entities = _load("entities.json")
        posts = _load("posts.json")
        if not isinstance(campaigns, list) or not isinstance(entities, list) or not isinstance(posts, list):
            _log("error", error_code="CONFLICT")
            return _err("CONFLICT", "Datastore is not in a valid state.")
    except Exception:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Failed to read datastore.")

    camp = next((c for c in campaigns if c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        _log("not_found", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Campaign not found.")

    ent = next((e for e in entities if e.get("id") == entity_id and e.get("campaign_id") == campaign_id and e.get("status") == "active"), None)
    if not ent:
        _log("not_found", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Entity not found.")

    idx = None
    for i, p in enumerate(posts):
        if p.get("id") == post_id and p.get("campaign_id") == campaign_id and p.get("entity_id") == entity_id:
            idx = i
            break
    if idx is None or posts[idx].get("status") != "active":
        _log("not_found", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Post not found.")

    post = posts[idx]

    # Uniqueness: unique(campaign_id, entity_id, name) among active posts
    if name is not None:
        if any(p.get("id") != post_id and p.get("campaign_id") == campaign_id and p.get("entity_id") == entity_id and p.get("name") == name and p.get("status") == "active" for p in posts):
            _log("conflict", error_code="CONFLICT")
            return _err("CONFLICT", "A post with this name already exists on the entity.")

    changed = False
    if name is not None and post.get("name") != name:
        post["name"] = name
        changed = True
    if entry is not None:
        if post.get("entry_html") != entry_html:
            post["entry_html"] = entry_html
            changed = True
    if position is not None:
        if post.get("position") != position:
            post["position"] = position
            changed = True
    if visibility_id is not None:
        if post.get("visibility_id") != visibility_id:
            post["visibility_id"] = visibility_id
            changed = True

    if not changed:
        _log("ok")
        return {"data": post, "meta": {"campaign_id": campaign_id, "entity_id": entity_id}}

    post["updated_at"] = _now()
    posts[idx] = post

    try:
        _save("posts.json", posts)
    except Exception:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "Failed to persist post.")

    _log("ok")
    return {
        "data": post,
        "meta": {
            "campaign_id": campaign_id,
            "entity_id": entity_id
        }
    }

def delete_post(campaign_id, entity_id, post_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_req_id():
        base = format(int(time.time() * 1000000), "x")
        return "knk_req_" + base[:26].ljust(26, "0")

    def _log(status_value, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "endpoint": "delete_post",
            "status": status_value,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "campaign_id": campaign_id,
            "entity_id": entity_id,
            "post_id": post_id
        })
        _save("request_logs.json", logs)

    def _limits_check():
        limits = _load("limits.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit")
        if isinstance(rl, dict):
            max_req = rl.get("max_requests")
            win = rl.get("window_seconds")
            if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                cutoff = now_dt - datetime.timedelta(seconds=win)
                cnt = 0
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts.endswith("Z"):
                        try:
                            dts = datetime.datetime.fromisoformat(ts[:-1])
                        except Exception:
                            continue
                        if dts >= cutoff:
                            cnt += 1
                if cnt >= max_req:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        quota = limits.get("quota")
        if isinstance(quota, dict):
            max_total = quota.get("max_requests_total")
            if isinstance(max_total, int) and max_total >= 0 and len(logs) >= max_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    # validate ids
    if not isinstance(campaign_id, str) or not re.match(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$", campaign_id):
        e = _err("VALIDATION_ERROR", "campaign_id is malformed.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e
    if not isinstance(entity_id, str) or not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", entity_id):
        e = _err("VALIDATION_ERROR", "entity_id is malformed.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e
    if not isinstance(post_id, str) or not re.match(r"^knk_pst_[0-9A-HJKMNP-TV-Z]{26}$", post_id):
        e = _err("VALIDATION_ERROR", "post_id is malformed.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e

    lim = _limits_check()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    camp = next((c for c in campaigns if isinstance(c, dict) and c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        e = _err("NOT_FOUND", "Campaign not found.")
        _log("error", e["error"]["code"])
        return e

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []
    ent = next((e for e in entities if isinstance(e, dict) and e.get("id") == entity_id and e.get("campaign_id") == campaign_id and e.get("status") == "active"), None)
    if not ent:
        e = _err("NOT_FOUND", "Entity not found.")
        _log("error", e["error"]["code"])
        return e

    posts = _load("posts.json")
    if not isinstance(posts, list):
        posts = []
    idx = None
    post = None
    for i, p in enumerate(posts):
        if isinstance(p, dict) and p.get("id") == post_id and p.get("campaign_id") == campaign_id and p.get("entity_id") == entity_id:
            idx = i
            post = p
            break

    if not post or post.get("status") == "deleted":
        e = _err("NOT_FOUND", "Post not found.")
        _log("error", e["error"]["code"])
        return e

    post2 = dict(post)
    post2["status"] = "deleted"
    post2["updated_at"] = now
    posts[idx] = post2
    _save("posts.json", posts)

    _log("ok", None)
    return {"data": post2}

def list_notes(campaign_id, limit=None, cursor=None, sort=None, order=None, include_deleted=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, credential_id=None, meta=None):
        # Best-effort request logging if a logs collection exists.
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                now = _iso_now()
                row = {
                    "id": f"knk_req_{int(time.time()*1000)}_{os.getpid()}",
                    "endpoint": "list_notes",
                    "status": status,
                    "timestamp": now,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "credential_id": credential_id,
                    "meta": meta or {}
                }
                rows.append(row)
                _save(fname, rows)
                return

    # Validate inputs
    if not isinstance(campaign_id, str) or not re.match(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$", campaign_id):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Malformed campaign_id.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid limit; must be integer in range 1–100.")

    if cursor is not None and not isinstance(cursor, str):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid cursor; must be a string.")

    if sort is None:
        sort = "created_at"
    if sort not in ("created_at", "updated_at", "name"):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid sort; must be one of: created_at, updated_at, name.")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid order; must be one of: asc, desc.")

    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid include_deleted; must be boolean.")

    # Authenticate/authorize (ambient). Choose any campaign that exists and is not deleted.
    campaigns = _load("campaigns.json")
    camp = next((c for c in campaigns if c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        # Real tool says FORBIDDEN for no access; our error codes list doesn't include FORBIDDEN; use UNAUTHORIZED.
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not authorized for campaign, or campaign not found.")

    entities = _load("entities.json")

    # Only notes for this campaign; status rules: active unless include_deleted.
    rows = []
    for e in entities:
        if e.get("campaign_id") != campaign_id:
            continue
        if e.get("entity_type") != "note":
            continue
        st = e.get("status")
        if include_deleted:
            if st not in ("active", "deleted"):
                continue
        else:
            if st != "active":
                continue
        rows.append(e)

    def _sort_key(r):
        v = r.get(sort)
        if sort in ("created_at", "updated_at"):
            # ISO8601 strings sort lexicographically when consistent; fallback empty.
            return v or ""
        return (v or "").lower()

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor: opaque string; we implement as "idx:<int>"
    start = 0
    if cursor:
        m = re.match(r"^idx:(\d+)$", cursor)
        if not m:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        start = int(m.group(1))
        if start < 0:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = f"idx:{start + limit}"

    _log("ok", meta={"count": len(page), "total": total})
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
            "include_deleted": include_deleted
        }
    }

def get_note(note_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_req_id():
        base = format(int(time.time() * 1000000), "x")
        return "knk_req_" + base[:26].ljust(26, "0")

    def _enforce_limits_and_log(status_value, error_code=None):
        limits = _load("limits.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        if isinstance(limits, dict):
            rl = limits.get("rate_limit")
            if isinstance(rl, dict):
                max_req = rl.get("max_requests")
                win = rl.get("window_seconds")
                if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                    cutoff = now_dt - datetime.timedelta(seconds=win)
                    cnt = 0
                    for r in logs:
                        ts = r.get("timestamp")
                        if isinstance(ts, str) and ts.endswith("Z"):
                            try:
                                dts = datetime.datetime.fromisoformat(ts[:-1])
                            except Exception:
                                continue
                            if dts >= cutoff:
                                cnt += 1
                    if cnt >= max_req:
                        logs.append({
                            "id": _new_req_id(),
                            "endpoint": "get_note",
                            "status": "error",
                            "error_code": "RATE_LIMIT",
                            "timestamp": now,
                            "latency_ms": int((time.time() - t0) * 1000),
                            "entity_id": note_id
                        })
                        _save("request_logs.json", logs)
                        return _err("RATE_LIMIT", "Rate limit exceeded.")

            quota = limits.get("quota")
            if isinstance(quota, dict):
                max_total = quota.get("max_requests_total")
                if isinstance(max_total, int) and max_total >= 0 and len(logs) >= max_total:
                    logs.append({
                        "id": _new_req_id(),
                        "endpoint": "get_note",
                        "status": "error",
                        "error_code": "QUOTA_EXCEEDED",
                        "timestamp": now,
                        "latency_ms": int((time.time() - t0) * 1000),
                        "entity_id": note_id
                    })
                    _save("request_logs.json", logs)
                    return _err("QUOTA_EXCEEDED", "Quota exceeded.")

        logs.append({
            "id": _new_req_id(),
            "endpoint": "get_note",
            "status": status_value,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "entity_id": note_id
        })
        _save("request_logs.json", logs)
        return None

    if not isinstance(note_id, str):
        e = _err("VALIDATION_ERROR", "note_id must be a string.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e
    if not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", note_id):
        e = _err("VALIDATION_ERROR", "note_id is malformed.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []

    ent = None
    for r in entities:
        if isinstance(r, dict) and r.get("id") == note_id and r.get("entity_type") == "note":
            ent = r
            break

    if not ent or ent.get("status") == "deleted":
        e = _err("NOT_FOUND", "Note not found.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e

    lim = _enforce_limits_and_log("ok", None)
    if lim:
        return lim
    return {"data": ent}

def create_note(campaign_id, name, entry=None, type=None, note_id=None, tags=None, entity_image_uuid=None, **_extra):
