    if note_id is not None:
        parent = next((e for e in entities if e.get("id") == note_id and e.get("campaign_id") == campaign_id and e.get("entity_type") == "note" and e.get("status") == "active"), None)
        if not parent:
            _log("error", meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Parent note not found or not active in this campaign.")

    # Tags must exist, same campaign, active
    wanted_tags = []
    if tags is not None:
        seen = set()
        for tid in tags:
            if tid in seen:
                continue
            seen.add(tid)
            tr = next((t for t in tags_rows if t.get("id") == tid and t.get("campaign_id") == campaign_id and t.get("status") == "active"), None)
            if not tr:
                _log("error", meta={"code": "NOT_FOUND"})
                return _err("NOT_FOUND", f"Tag not found or inactive in this campaign: {tid}")
            wanted_tags.append(tr)

    # Generate ids and enforce uniqueness constraints
    # - unique(campaign_id, entity_type, kanka_object_id)
    # - unique(campaign_id, kanka_entity_id)
    used_kanka_entity_ids = {e.get("kanka_entity_id") for e in entities if e.get("campaign_id") == campaign_id}
    used_kanka_object_ids = {e.get("kanka_object_id") for e in entities if e.get("campaign_id") == campaign_id and e.get("entity_type") == "note"}

    def _next_int(used, start=1):
        x = start
        while x in used:
            x += 1
        return x

    new_kanka_entity_id = _next_int(used_kanka_entity_ids, 1)
    new_kanka_object_id = _next_int(used_kanka_object_ids, 1)

    # New internal id (ULID-like) - deterministic enough for offline: prefix + base32 time+counter
    alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _enc32(n, length):
        s = ""
        for _ in range(length):
            s = alphabet[n % 32] + s
            n //= 32
        return s

    ms = int(time.time() * 1000)
    # 26 chars typical ULID payload; make 26 from time and pid entropy
    payload = _enc32(ms, 10) + _enc32((os.getpid() ^ (ms & 0xFFFFFFFF)), 16)
    new_id = "knk_ent_" + payload[:26]

    if any(e.get("id") == new_id for e in entities):
        # Extremely unlikely; adjust with time bump
        ms2 = ms + 1
        payload = _enc32(ms2, 10) + _enc32((os.getpid() ^ (ms2 & 0xFFFFFFFF)), 16)
        new_id = "knk_ent_" + payload[:26]
        if any(e.get("id") == new_id for e in entities):
            _log("error", meta={"code": "CONFLICT"})
            return _err("CONFLICT", "ID collision; retry.")

    now = _iso_now()
    row = {
        "id": new_id,
        "campaign_id": campaign_id,
        "kanka_entity_id": new_kanka_entity_id,
        "entity_type": "note",
        "kanka_object_id": new_kanka_object_id,
        "name": name.strip(),
        "entry_html": entry,
        "type_label": type,
        "title": None,
        "age": None,
        "sex": None,
        "pronouns": None,
        "race_id": None,
        "is_destroyed": None,
        "date": None,
        "author_id": None,
        "entity_image_uuid": entity_image_uuid,
        "parent_entity_id": note_id,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # Enforce parent not self (already impossible) and no cycles (new node cannot create cycle if parent exists)
    # Save entity
    entities.append(row)

    # Replace entity_tags for this entity to match provided list (idempotent)
    if tags is not None:
        # remove any existing (should be none)
        entity_tags = [et for et in entity_tags if et.get("entity_id") != new_id]
        for tr in wanted_tags:
            et_id = "knk_etg_" + payload[:26]  # reuse payload base; adjust per tag
            # ensure unique
            while any(et.get("id") == et_id for et in entity_tags):
                ms += 1
                payload2 = _enc32(ms, 10) + _enc32((os.getpid() ^ (ms & 0xFFFFFFFF)), 16)
                et_id = "knk_etg_" + payload2[:26]
            entity_tags.append({
                "id": et_id,
                "campaign_id": campaign_id,
                "entity_id": new_id,
                "tag_id": tr.get("id"),
                "created_at": now,
                "updated_at": now
            })

    _save("entities.json", entities)
    if tags is not None:
        _save("entity_tags.json", entity_tags)

    _log("ok", meta={"id": new_id})
    return {"data": row}

def update_note(campaign_id, note_id, name=None, entry=None, type=None, parent_note_id=None, tags=None, entity_image_uuid=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status, meta=None):
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                rows = _load(fname)
                rows.append({
                    "id": f"knk_req_{int(time.time()*1000)}_{os.getpid()}",
                    "endpoint": "update_note",
                    "status": status,
                    "timestamp": _iso_now(),
                    "latency_ms": int((time.time() - t0) * 1000),
                    "meta": meta or {}
                })
                _save(fname, rows)
                return

    # Validate
    if not isinstance(campaign_id, str) or not re.match(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$", campaign_id):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Malformed campaign_id.")
    if not isinstance(note_id, str) or not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", note_id):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Malformed note_id.")

    if name is not None and (not isinstance(name, str) or len(name.strip()) < 1):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid name; must be a non-empty string.")
    if entry is not None and not isinstance(entry, str):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid entry; must be a string.")
    if type is not None and not isinstance(type, str):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid type; must be a string.")
    if entity_image_uuid is not None and not isinstance(entity_image_uuid, str):
        _log("error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid entity_image_uuid; must be a string.")
    if parent_note_id is not None:
        if not isinstance(parent_note_id, str) or not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", parent_note_id):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Malformed parent_note_id.")

    if tags is not None:
        if not isinstance(tags, list):
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid tags; must be an array of tag ids.")
        for tid in tags:
            if not isinstance(tid, str) or not re.match(r"^knk_tag_[0-9A-HJKMNP-TV-Z]{26}$", tid):
                _log("error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid tag id in tags.")

    # Campaign must exist and not be deleted
    campaigns = _load("campaigns.json")
    camp = next((c for c in campaigns if c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        _log("error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Not authorized for campaign, or campaign not found.")

    entities = _load("entities.json")
    idx = next((i for i, e in enumerate(entities) if e.get("id") == note_id and e.get("entity_type") == "note"), None)
    if idx is None:
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Note not found.")
    note = entities[idx]

    if note.get("campaign_id") != campaign_id:
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Note not found in campaign.")
    if note.get("status") == "deleted":
        _log("error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Note not found.")

    # Parent update: must be same campaign, type note, active; no self-parent; prevent cycles
    if parent_note_id is not None:
        if parent_note_id == note_id:
            _log("error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "parent_note_id cannot be the note itself.")
        parent = next((e for e in entities if e.get("id") == parent_note_id and e.get("campaign_id") == campaign_id and e.get("entity_type") == "note" and e.get("status") == "active"), None)
        if not parent:
            _log("error", meta={"code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Parent note not found or not active in this campaign.")

        # Cycle check: walk up from parent to root; must not encounter note_id
        seen = set()
        cur = parent
        while cur is not None:
            cid = cur.get("id")
            if cid == note_id:
                _log("error", meta={"code": "CONFLICT"})
                return _err("CONFLICT", "Parent assignment would create a cycle.")
            if cid in seen:
                break
            seen.add(cid)
            pid = cur.get("parent_entity_id")
            if not pid:
                break
            cur = next((e for e in entities if e.get("id") == pid and e.get("campaign_id") == campaign_id and e.get("entity_type") == "note"), None)

    # Tags: must exist, same campaign, active; then replace entity_tags to match
    tags_rows = _load("tags.json")
    entity_tags = _load("entity_tags.json")
    wanted_tag_ids = None
    if tags is not None:
        dedup = []
        seen = set()
        for tid in tags:
            if tid in seen:
                continue
            seen.add(tid)
            tr = next((t for t in tags_rows if t.get("id") == tid and t.get("campaign_id") == campaign_id and t.get("status") == "active"), None)
            if not tr:
                _log("error", meta={"code": "NOT_FOUND"})
                return _err("NOT_FOUND", f"Tag not found or inactive in this campaign: {tid}")
            dedup.append(tid)
        wanted_tag_ids = dedup

    # Apply patch
    changed = False
    if name is not None and note.get("name") != name.strip():
        note["name"] = name.strip()
        changed = True
    if entry is not None and note.get("entry_html") != entry:
        note["entry_html"] = entry
        changed = True
    if type is not None and note.get("type_label") != type:
        note["type_label"] = type
        changed = True
    if entity_image_uuid is not None and note.get("entity_image_uuid") != entity_image_uuid:
        note["entity_image_uuid"] = entity_image_uuid
        changed = True
    if parent_note_id is not None and note.get("parent_entity_id") != parent_note_id:
        note["parent_entity_id"] = parent_note_id
        changed = True

    # Update tags set (idempotent)
    if wanted_tag_ids is not None:
        existing = [et for et in entity_tags if et.get("entity_id") == note_id]
        existing_ids = sorted([et.get("tag_id") for et in existing if et.get("campaign_id") == campaign_id])
        if sorted(wanted_tag_ids) != existing_ids:
            # remove all current for this entity in campaign
            entity_tags = [et for et in entity_tags if not (et.get("entity_id") == note_id and et.get("campaign_id") == campaign_id)]
            now = _iso_now()
            # make deterministic-ish ids
            alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
            def _enc32(n, length):
                s = ""
                for _ in range(length):
                    s = alphabet[n % 32] + s
                    n //= 32
                return s
            base = _enc32(int(time.time() * 1000), 10) + _enc32(os.getpid(), 16)
            j = 0
            for tid in wanted_tag_ids:
                et_id = "knk_etg_" + (base[j:j+26].ljust(26, "0"))
                j = (j + 1) % max(1, len(base))
                while any(et.get("id") == et_id for et in entity_tags):
                    et_id = "knk_etg_" + _enc32(int(time.time() * 1000) + j, 26)
                entity_tags.append({
                    "id": et_id,
                    "campaign_id": campaign_id,
                    "entity_id": note_id,
                    "tag_id": tid,
                    "created_at": now,
                    "updated_at": now
                })
            changed = True

    if not changed:
        # No success without effect: but patch with no changes should be idempotent success (real APIs usually do).
        # We'll still refresh updated_at only if a field changed.
        _log("ok", meta={"id": note_id, "changed": False})
        return {"data": note}

    note["updated_at"] = _iso_now()
    entities[idx] = note

    _save("entities.json", entities)
    if wanted_tag_ids is not None:
        _save("entity_tags.json", entity_tags)

    _log("ok", meta={"id": note_id, "changed": True})
    return {"data": note}

def delete_note(campaign_id, note_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_req_id():
        base = format(int(time.time() * 1000000), "x")
        return "knk_req_" + base[:26].ljust(26, "0")

    def _log(status_value, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _new_req_id(),
            "endpoint": "delete_note",
            "status": status_value,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "campaign_id": campaign_id,
            "entity_id": note_id
        })
        _save("request_logs.json", logs)

    def _limits_check():
        limits = _load("limits.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if not isinstance(limits, dict):
            return None
        rl = limits.get("rate_limit")
        if isinstance(rl, dict):
            max_req = rl.get("max_requests")
            win = rl.get("window_seconds")
            if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                cutoff = now_dt - datetime.timedelta(seconds=win)
                cnt = 0
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts.endswith("Z"):
                        try:
                            dts = datetime.datetime.fromisoformat(ts[:-1])
                        except Exception:
                            continue
                        if dts >= cutoff:
                            cnt += 1
                if cnt >= max_req:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        quota = limits.get("quota")
        if isinstance(quota, dict):
            max_total = quota.get("max_requests_total")
            if isinstance(max_total, int) and max_total >= 0 and len(logs) >= max_total:
                return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    if not isinstance(campaign_id, str) or not re.match(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$", campaign_id):
        e = _err("VALIDATION_ERROR", "campaign_id is malformed.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e
    if not isinstance(note_id, str) or not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", note_id):
        e = _err("VALIDATION_ERROR", "note_id is malformed.")
        lim = _limits_check()
        if lim:
            _log("error", lim["error"]["code"])
            return lim
        _log("error", e["error"]["code"])
        return e

    lim = _limits_check()
    if lim:
        _log("error", lim["error"]["code"])
        return lim

    campaigns = _load("campaigns.json")
    if not isinstance(campaigns, list):
        campaigns = []
    camp = next((c for c in campaigns if isinstance(c, dict) and c.get("id") == campaign_id and c.get("status") != "deleted"), None)
    if not camp:
        e = _err("NOT_FOUND", "Campaign not found.")
        _log("error", e["error"]["code"])
        return e

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []
    idx = None
    ent = None
    for i, r in enumerate(entities):
        if isinstance(r, dict) and r.get("id") == note_id and r.get("entity_type") == "note" and r.get("campaign_id") == campaign_id:
            idx = i
            ent = r
            break
    if not ent or ent.get("status") == "deleted":
        e = _err("NOT_FOUND", "Note not found.")
        _log("error", e["error"]["code"])
        return e

    ent2 = dict(ent)
    ent2["status"] = "deleted"
    ent2["updated_at"] = now
    entities[idx] = ent2
    _save("entities.json", entities)

    _log("ok", None)
    return {"data": ent2}

def list_journals(campaign_id, limit=None, cursor=None, sort=None, order=None, include_deleted=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_used=None):
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                rows.append({
                    "id": "req_" + os.urandom(8).hex(),
                    "endpoint": "list_journals",
                    "timestamp": now,
                    "status": status_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "credential": credential_used
                })
                _save(fname, rows)
                break

    def _b64d(s):
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("utf-8")).decode("utf-8")

    def _b64e(s):
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("utf-8").rstrip("=")

    try:
        if not isinstance(campaign_id, str) or not re.match(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$", campaign_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "campaign_id is malformed.")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")

        if cursor is not None and not isinstance(cursor, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.")

        if sort is None:
            sort = "created_at"
        if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "name", "date"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name, date.")

        if order is None:
            order = "asc"
        if not isinstance(order, str) or order not in ("asc", "desc"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'.")

        if include_deleted is None:
            include_deleted = False
        if not isinstance(include_deleted, bool):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "include_deleted must be a boolean.")

        campaigns = _load("campaigns.json")
        camp = next((c for c in campaigns if c.get("id") == campaign_id), None)
        if not camp or camp.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Campaign not found.")

        entities = _load("entities.json")
        rows = []
        for e in entities:
            if e.get("campaign_id") != campaign_id:
                continue
            if e.get("entity_type") != "journal":
                continue
            st = e.get("status")
            if st == "deleted" and not include_deleted:
                continue
            if st != "active" and st != "deleted":
                continue
            rows.append(e)

        def _sort_key(e):
            v = e.get(sort)
            # Normalize for None and consistent comparisons
            if sort in ("created_at", "updated_at"):
                return (v is None, v or "")
            if sort == "name":
                return (v is None, (v or "").lower(), e.get("created_at") or "", e.get("id") or "")
            if sort == "date":
                # Date is a free-form string; sort lexicographically, None last
                return (v is None, v or "", e.get("created_at") or "", e.get("id") or "")
            return (v is None, v or "")

        rows.sort(key=_sort_key, reverse=(order == "desc"))

        start = 0
        if cursor:
            try:
                decoded = _b64d(cursor)
                # Expect "offset:<n>"
                if not decoded.startswith("offset:"):
                    _log("VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "cursor is invalid.")
                start = int(decoded.split(":", 1)[1])
                if start < 0:
                    raise ValueError()
            except (ValueError, UnicodeDecodeError, base64.binascii.Error):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid.")

        page = rows[start:start + limit]
        next_cursor = None
        has_more = start + limit < len(rows)
        if has_more:
            next_cursor = _b64e(f"offset:{start + limit}")

        _log("OK")
        return {
            "data": page,
            "meta": {
                "total": len(rows),
                "limit": limit,
                "cursor": cursor,
                "has_more": has_more,
                "next_cursor": next_cursor,
                "sort": sort,
                "order": order,
                "include_deleted": include_deleted
            }
        }
    except Exception as e:
        _log("CONFLICT")
        return _err("CONFLICT", "Unable to list journals due to an unexpected condition.", detail=str(e))

def get_journal(journal_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_req_id():
        base = format(int(time.time() * 1000000), "x")
        return "knk_req_" + base[:26].ljust(26, "0")

    def _enforce_limits_and_log(status_value, error_code=None):
        limits = _load("limits.json")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        if isinstance(limits, dict):
            rl = limits.get("rate_limit")
            if isinstance(rl, dict):
                max_req = rl.get("max_requests")
                win = rl.get("window_seconds")
                if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                    cutoff = now_dt - datetime.timedelta(seconds=win)
                    cnt = 0
                    for r in logs:
                        ts = r.get("timestamp")
                        if isinstance(ts, str) and ts.endswith("Z"):
                            try:
                                dts = datetime.datetime.fromisoformat(ts[:-1])
                            except Exception:
                                continue
                            if dts >= cutoff:
                                cnt += 1
                    if cnt >= max_req:
                        logs.append({
                            "id": _new_req_id(),
                            "endpoint": "get_journal",
                            "status": "error",
                            "error_code": "RATE_LIMIT",
                            "timestamp": now,
                            "latency_ms": int((time.time() - t0) * 1000),
                            "entity_id": journal_id
                        })
                        _save("request_logs.json", logs)
                        return _err("RATE_LIMIT", "Rate limit exceeded.")

            quota = limits.get("quota")
            if isinstance(quota, dict):
                max_total = quota.get("max_requests_total")
                if isinstance(max_total, int) and max_total >= 0 and len(logs) >= max_total:
                    logs.append({
                        "id": _new_req_id(),
                        "endpoint": "get_journal",
                        "status": "error",
                        "error_code": "QUOTA_EXCEEDED",
                        "timestamp": now,
                        "latency_ms": int((time.time() - t0) * 1000),
                        "entity_id": journal_id
                    })
                    _save("request_logs.json", logs)
                    return _err("QUOTA_EXCEEDED", "Quota exceeded.")

        logs.append({
            "id": _new_req_id(),
            "endpoint": "get_journal",
            "status": status_value,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "entity_id": journal_id
        })
        _save("request_logs.json", logs)
        return None

    if not isinstance(journal_id, str):
        e = _err("VALIDATION_ERROR", "journal_id must be a string.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e
    if not re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", journal_id):
        e = _err("VALIDATION_ERROR", "journal_id is not a valid journal ULID.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e

    entities = _load("entities.json")
    if not isinstance(entities, list):
        entities = []

    ent = None
    for r in entities:
        if isinstance(r, dict) and r.get("id") == journal_id and r.get("entity_type") == "journal":
            ent = r
            break

    if not ent or ent.get("status") == "deleted":
        e = _err("NOT_FOUND", "Journal not found.")
        _enforce_limits_and_log("error", e["error"]["code"])
        return e

    lim = _enforce_limits_and_log("ok", None)
    if lim:
        return lim
    return {"data": ent}

def create_journal(campaign_id, name, entry=None, type=None, date=None, journal_id=None, author_id=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0500000" if __import__("os").path.isdir("./environment_mix/0500000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_used=None):
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                rows.append({
                    "id": "req_" + os.urandom(8).hex(),
                    "endpoint": "create_journal",
                    "timestamp": now,
                    "status": status_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "credential": credential_used
                })
                _save(fname, rows)
                break

    def _is_ulid(s):
        return isinstance(s, str) and re.match(r"^knk_ent_[0-9A-HJKMNP-TV-Z]{26}$", s)

    def _is_cmp_ulid(s):
        return isinstance(s, str) and re.match(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$", s)

    def _new_id(prefix):
        # Not a real ULID, but conforms to allowed charset/pattern.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))

    def _wrap_html(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        t = s.strip()
        if t == "":
            return ""
        # If it looks like it already has HTML tags, keep it.
        if re.search(r"<[^>]+>", t):
            return s
        return f"<p>{s}</p>"

    try:
        if not _is_cmp_ulid(campaign_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "campaign_id is malformed.")
        if not isinstance(name, str) or len(name) < 1 or name.strip() == "":
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name is required and cannot be empty.")

        if entry is not None and not isinstance(entry, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "entry must be a string.")
        if type is not None and not isinstance(type, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "type must be a string.")
        if date is not None and not isinstance(date, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "date must be a string.")
        if journal_id is not None and not _is_ulid(journal_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "journal_id (parent) is malformed.")
        if author_id is not None and not isinstance(author_id, int):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "author_id must be an integer.")

        campaigns = _load("campaigns.json")
        camp = next((c for c in campaigns if c.get("id") == campaign_id), None)
        if not camp or camp.get("status") == "deleted":
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Campaign not found.")

        entities = _load("entities.json")

        parent = None
        if journal_id is not None:
            parent = next((e for e in entities if e.get("id") == journal_id), None)
            if not parent or parent.get("status") == "deleted":
                _log("NOT_FOUND")
                return _err("NOT_FOUND", "Parent journal not found.")
            if parent.get("campaign_id") != campaign_id:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Parent journal must belong to the same campaign.")
            if parent.get("entity_type") != "journal":
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Parent entity must be a journal.")
            # Cycle prevention: parent cannot be the new entity (always true), but ensure no self-parenting via reuse of id doesn't apply

        # Generate upstream numeric IDs with uniqueness constraints
        used_kanka_entity_ids = {e.get("kanka_entity_id") for e in entities if e.get("campaign_id") == campaign_id}
        used_obj_ids = {e.get("kanka_object_id") for e in entities if e.get("campaign_id") == campaign_id and e.get("entity_type") == "journal"}

        def _new_int_id(used):
            # Prefer max+1 if possible; otherwise random.
            ints = [x for x in used if isinstance(x, int)]
            nxt = (max(ints) + 1) if ints else 1
            while nxt in used:
                nxt += 1
            return nxt

        kanka_entity_id = _new_int_id(used_kanka_entity_ids)
        kanka_object_id = _new_int_id(used_obj_ids)

        # Ensure internal id is unique
        new_id = _new_id("knk_ent")
        existing_ids = {e.get("id") for e in entities}
        tries = 0
        while new_id in existing_ids and tries < 10:
            new_id = _new_id("knk_ent")
            tries += 1
        if new_id in existing_ids:
            _log("CONFLICT")
            return _err("CONFLICT", "Unable to allocate a unique journal id.")

        entry_html = _wrap_html(entry) if entry is not None else None
        if entry is not None and entry_html is None:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "entry must be a string.")

        row = {
            "id": new_id,
            "campaign_id": campaign_id,
            "kanka_entity_id": kanka_entity_id,
            "entity_type": "journal",
            "kanka_object_id": kanka_object_id,
            "name": name,
            "entry_html": entry_html,
            "type_label": type if type is not None else None,
            "title": None,
            "age": None,
            "sex": None,
            "pronouns": None,
            "race_id": None,
            "is_destroyed": None,
            "date": date if date is not None else None,
            "author_id": author_id if author_id is not None else None,
            "entity_image_uuid": None,
            "parent_entity_id": journal_id if journal_id is not None else None,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }

        # Enforce constraints: name <> '' already checked; parent_entity_id != id
        if row["parent_entity_id"] == row["id"]:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parent_entity_id cannot be self.")

        # Uniqueness: (campaign_id, entity_type, kanka_object_id), (campaign_id, kanka_entity_id)
        for e in entities:
            if e.get("campaign_id") != campaign_id:
                continue
            if e.get("kanka_entity_id") == kanka_entity_id:
                _log("CONFLICT")
                return _err("CONFLICT", "kanka_entity_id must be unique within the campaign.")
            if e.get("entity_type") == "journal" and e.get("kanka_object_id") == kanka_object_id:
                _log("CONFLICT")
                return _err("CONFLICT", "kanka_object_id must be unique for journals within the campaign.")

        entities.append(row)
        _save("entities.json", entities)

        _log("OK")
        return {"data": row}
    except Exception as e:
        _log("CONFLICT")
        return _err("CONFLICT", "Unable to create journal due to an unexpected condition.", detail=str(e))

