    if parent_journal_id is not None:
        if parent_journal_id == journal_id:
            e = _err("VALIDATION_ERROR", "parent_journal_id cannot reference the journal itself.")
            _log("error", e["error"]["code"])
            return e
        parent = next((p for p in entities if isinstance(p, dict) and p.get("id") == parent_journal_id), None)
        if not parent or parent.get("status") == "deleted":
