            return e
        if parent.get("entity_type") != "journal":
            e = _err("CONFLICT", "Parent entity must be a journal.")
            _log("error", e["error"]["code"])
            return e

    updated = dict(ent)
    if name is not None:
        updated["name"] = name
    if entry is not None:
        updated["entry_html"] = entry
    if type is not None:
        updated["type_label"] = type
    if date is not None:
