    def _ensure_list(x): return x if isinstance(x, list) else []

    def _log(status_value, error_code=None, meta=None):
        logs = _ensure_list(_load("request_logs.json"))
        logs.append({
            "id": "knk_req_" + hashlib.sha256((now + str(time.time()) + "update_campaign").encode("utf-8")).hexdigest()[:26],
            "endpoint": "update_campaign",
            "status": status_value,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
            "campaign_id": campaign_id,
            "meta": meta if isinstance(meta, dict) else {}
        })
        _save("request_logs.json", logs)

    def _limits_check():
        limits = _load("limits.json")
        if not isinstance(limits, dict):
            return None
        logs = _ensure_list(_load("request_logs.json"))
        rl = limits.get("rate_limit")
        if isinstance(rl, dict):
            max_req = rl.get("max_requests")
            win = rl.get("window_seconds")
            if isinstance(max_req, int) and isinstance(win, int) and win > 0 and max_req >= 0:
                cutoff = now_dt - datetime.timedelta(seconds=win)
                cnt = 0
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str) and ts.endswith("Z"):
                        try:
                            dts = datetime.datetime.fromisoformat(ts[:-1])
                        except Exception:
                            continue
                        if dts >= cutoff:
                            cnt += 1
                if cnt >= max_req:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        quota = limits.get("quota")
        if isinstance(quota, dict):
            max_total = quota.get("max_requests_total")
            if isinstance(max_total, int) and max_total >= 0:
                if len(logs) >= max_total:
                    return _err("QUOTA_EXCEEDED", "Quota exceeded.")
        return None

    pat_cmp = re.compile(r"^knk_cmp_[0-9A-HJKMNP-TV-Z]{26}$")
    if not isinstance(campaign_id, str) or not pat_cmp.match(campaign_id):
        _log("error", "VALIDATION_ERROR", {"field": "campaign_id"})
        return _err("VALIDATION_ERROR", "campaign_id is malformed.", field="campaign_id")
    if name is not None and (not isinstance(name, str) or name == ""):
        _log("error", "VALIDATION_ERROR", {"field": "name"})
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided.", field="name")
    if description is not None and not isinstance(description, str):
        _log("error", "VALIDATION_ERROR", {"field": "description"})
        return _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")
    if status is not None and (not isinstance(status, str) or status not in ("active", "archived", "deleted")):
        _log("error", "VALIDATION_ERROR", {"field": "status"})
        return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.", field="status")

    lim_err = _limits_check()
    if lim_err:
        _log("error", lim_err["error"]["code"])
        return lim_err

    campaigns = _ensure_list(_load("campaigns.json"))
    idx = None
    camp = None
    for i, c in enumerate(campaigns):
        if isinstance(c, dict) and c.get("id") == campaign_id:
            idx = i
            camp = c
            break
    if camp is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Campaign not found.")

    cur_status = camp.get("status")
    if cur_status not in ("active", "archived", "deleted"):
        _log("error", "CONFLICT", {"stored_status": cur_status})
        return _err("CONFLICT", "Campaign has an invalid stored status.", status=cur_status)

    transitions = {
        "active": {"archived", "deleted"},
        "archived": {"active", "deleted"},
        "deleted": set()
    }

    changed = False

    if name is not None and camp.get("name") != name:
        camp["name"] = name
        changed = True

    if description is not None and camp.get("description") != description:
        camp["description"] = description
        changed = True

    if status is not None and status != cur_status:
        if status not in transitions.get(cur_status, set()):
            _log("error", "INVALID_TRANSITION", {"from_status": cur_status, "to_status": status})
            return _err("INVALID_TRANSITION", "Invalid campaign status transition.", from_status=cur_status, to_status=status)
        camp["status"] = status
        changed = True

    if not changed:
        # Patch semantics: if nothing changes, return the existing resource (idempotent success).
        _log("ok", None, {"changed": False})
        return {"data": camp, "meta": {"changed": False}}

    camp["updated_at"] = now
    campaigns[idx] = camp
    _save("campaigns.json", campaigns)

    _log("ok", None, {"changed": True})
    return {"data": camp, "meta": {"changed": True}}
